mapper.update:
UPDATE cost_archive_manifest
   SET raw_purged = 1, raw_purged_at = NOW(), updated_at = NOW()
 WHERE `year_month` = #{yearMonth} AND csp = #{csp}

mapper.select:
SELECT CASE WHEN COUNT(*) > 0 AND SUM(certifed_fixed_yn = 'Y') = COUNT(*) THEN 1 ELSE 0 END
  FROM cur_process_info
 WHERE csp = 'AWS' AND collect_date = #{yearMonth}
